solution.code:
public class Main {
    public static void main(String[] args) {
        Dog d = new Dog("Rex");
        Cat c = new Cat("Tom");
        d.eat();
        c.eat();
        d.speak();
        c.speak();
    }
}

class Animal {
    protected String name;

    Animal(String name) {
        this.name = name;
    }

    void eat() {
        System.out.println(name + " is eating");
    }
}

class Dog extends Animal {
    Dog(String name) {
        super(name);
    }

    void speak() {
        System.out.println(name + " says Woof");
    }
}

class Cat extends Animal {
    Cat(String name) {
        super(name);
    }

    void speak() {
        System.out.println(name + " says Meow");
    }
}
